// Live preview: switches theme, Dynamix base and icon set on the dashboard
// mock-up in the iframe. Data comes from live/data.js, generated by
// scripts/render_previews.py. The choice is kept in the URL
// (?theme=nord&mode=dark&icons=tabler), so a preview can be linked.
(function () {
  'use strict';

  var THEMES = window.THEMER_THEMES || [];
  var ICONS = window.THEMER_ICONS || {};
  var SET_NAMES = {
    lucide: 'Lucide', tabler: 'Tabler', phosphor: 'Phosphor', heroicons: 'Heroicons',
    iconoir: 'Iconoir', remix: 'Remix', bootstrap: 'Bootstrap', carbon: 'Carbon', material: 'Material'
  };
  var frame = document.getElementById('dash');
  var chips = document.getElementById('theme-chips');
  var modes = document.getElementById('mode');
  var sets = document.getElementById('iconsets');
  var desc = document.getElementById('theme-desc');

  var params = new URLSearchParams(location.search);
  var state = {
    theme: byStem(params.get('theme')) || THEMES[0],
    base: params.get('mode') === 'dark' ? 'black' : (params.get('mode') === 'light' ? 'white' : null),
    icons: ICONS[params.get('icons')] ? params.get('icons') : 'lucide'
  };

  function byStem(stem) {
    for (var i = 0; i < THEMES.length; i++) if (THEMES[i].stem === stem) return THEMES[i];
    return null;
  }

  // a theme made for one base is only shown on that base
  function baseFor(theme) {
    return theme.bases.indexOf(state.base) !== -1 ? state.base : theme.bases[0];
  }

  function el(tag, attrs, text) {
    var e = document.createElement(tag);
    for (var k in attrs) e.setAttribute(k, attrs[k]);
    if (text) e.textContent = text;
    return e;
  }

  THEMES.forEach(function (t) {
    var b = el('button', { type: 'button', 'data-stem': t.stem, 'aria-pressed': 'false', title: t.description });
    var strip = el('span', { 'class': 'chip__strip', 'aria-hidden': 'true' });
    t.swatch.forEach(function (c) { var i = el('i'); i.style.background = c; strip.appendChild(i); });
    b.appendChild(strip);
    b.appendChild(el('span', { 'class': 'chip__name' }, t.name));
    chips.appendChild(b);
  });
  Object.keys(SET_NAMES).forEach(function (s) {
    sets.appendChild(el('button', { type: 'button', 'data-set': s, 'aria-pressed': 'false' }, SET_NAMES[s]));
  });

  function apply() {
    var doc = frame.contentDocument;
    var base = baseFor(state.theme);
    if (doc && doc.documentElement) {
      doc.documentElement.className = 'Theme--' + base;
      var link = doc.getElementById('theme');
      if (link) link.setAttribute('href', 'themes/' + state.theme.file);
      var icons = ICONS[state.icons] || {};
      doc.querySelectorAll('svg[data-icon]').forEach(function (svg) {
        var markup = icons[svg.getAttribute('data-icon')];
        if (markup) svg.outerHTML = markup;
      });
    }
    chips.querySelectorAll('button').forEach(function (b) {
      b.setAttribute('aria-pressed', b.getAttribute('data-stem') === state.theme.stem ? 'true' : 'false');
    });
    modes.querySelectorAll('button').forEach(function (b) {
      var v = b.getAttribute('data-base');
      b.setAttribute('aria-pressed', v === base ? 'true' : 'false');
      b.disabled = state.theme.bases.indexOf(v) === -1;
    });
    sets.querySelectorAll('button').forEach(function (b) {
      b.setAttribute('aria-pressed', b.getAttribute('data-set') === state.icons ? 'true' : 'false');
    });
    desc.textContent = state.theme.name + ': ' + state.theme.description +
      (state.theme.bases.length === 1 ? ' Made for ' + (base === 'white' ? 'light' : 'dark') + ' mode only.' : '');
    var q = new URLSearchParams({ theme: state.theme.stem, mode: base === 'white' ? 'light' : 'dark', icons: state.icons });
    history.replaceState(null, '', '?' + q.toString());
  }

  chips.addEventListener('click', function (e) {
    var b = e.target.closest('button[data-stem]');
    if (b) { state.theme = byStem(b.getAttribute('data-stem')); apply(); }
  });
  modes.addEventListener('click', function (e) {
    var b = e.target.closest('button[data-base]');
    if (b && !b.disabled) { state.base = b.getAttribute('data-base'); apply(); }
  });
  sets.addEventListener('click', function (e) {
    var b = e.target.closest('button[data-set]');
    if (b) { state.icons = b.getAttribute('data-set'); apply(); }
  });

  frame.addEventListener('load', apply);
  if (frame.contentDocument && frame.contentDocument.readyState === 'complete') apply();
})();
